insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-arrae-mb-1', 'Arrae MB-1 Metabolism Support', 'Arrae', 'supplement', 'physical', 'A daily capsule sold for metabolism, cravings, and weight management. It combines African mango seed extract (IGOB131), Cissus leaf extract (CQR-300), green tea extract, grains of paradise, chromium, vitamin B6, and the probiotic Bifidobacterium lactis B420. Arrae claims body weight reductions of up to 12%, fewer cravings, more daily calorie burn, and healthy blood sugar, and footnotes that these figures are based on research on individual ingredients, not on MB-1 itself. Contains caffeine from green tea. The serving is 2 capsules a day.', '$55 for a 1-month supply on arrae.com ($44 a month by subscription); on Amazon $52.49 for 60 capsules or $27.99 for 40', 'https://m.media-amazon.com/images/I/51cUawzhbWL._AC_SL500_.jpg', 'https://arrae.com/products/mb-1', '["arrae","mb-1","metabolism","weight management","cravings","african mango","cissus","green tea","chromium","probiotic","caffeine","supplement"]'::jsonb, '["supplement"]'::jsonb, '["arrae.com","Amazon"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"A dietary supplement, which the FDA does not evaluate for safety or efficacy. The label says its statements have not been evaluated by the FDA and that it is not intended to diagnose, treat, cure, or prevent any disease.","materials":"Vegetable capsules; 2 a day. Amazon sells 40- and 60-capsule bottles; Arrae sells a 1-month supply. Contains caffeine from green tea extract; the amount isn''t stated. Arrae says it is third-party tested and links a certificate of analysis.","recalls":"No recalls found.","sideEffects":"Per the label on Amazon: don''t take it if you are pregnant or nursing, under 18, have a medical condition, take any medications, have a history of liver problems, or on an empty stomach, or on a day you take other green tea products. Don''t exceed 1 serving a day. Green tea extract has been linked to rare liver injury, with higher risk on an empty stomach, and chromium can lower blood sugar with diabetes medicines (NIH). Full warnings are listed below.","opinionAlerts":"Weight-loss claims: Arrae''s \"up to 12%\" figure comes from ingredient research, not from a study of MB-1. The main study behind it was a 10-week trial of 72 people by one research group, and reviews of African mango call the evidence limited by small, flawed trials. The blend''s amounts are not disclosed, so the doses can''t be compared with the studies. Liver caution: contains green tea extract. Not for anyone pregnant, nursing, under 18, on medications, or with liver problems (per the label)."}'::jsonb, 'Arrae says MB-1 reduces body weight by up to 12%, curbs cravings, raises daily calorie burn, and supports healthy blood sugar, and footnotes that these figures are "based on individual ingredient research." No study of MB-1 itself was found, so what follows is what the research says about its ingredients.

The weight claims trace mainly to African mango (IGOB131) combined with Cissus (CQR-300). In a 10-week, double-blind, placebo-controlled trial by a research group in Cameroon, 72 adults with overweight or obesity took Cissus alone, Cissus with African mango, or a placebo, with no diet or exercise changes. Both active groups lost more weight and body fat and had lower cholesterol and blood sugar than placebo, with larger changes for the combination. NIH''s Office of Dietary Supplements (ODS) notes that the African mango trials were all run by the same group of authors. A 2013 systematic review found three such trials, all with flaws in how they were reported, and concluded the effect was unproven and African mango can''t be recommended for weight loss. A 2020 meta-analysis of five trials rated four as having a high risk of bias, and the one well-run trial found no significant difference. MB-1 lists both extracts inside an 895 mg blend without saying how much of each it contains, so its doses can''t be compared with the trials.

For the other ingredients, the evidence is small. ODS says chromium produced only about 1 kg more weight loss than placebo in reviews of trials, and green tea''s effect on weight is small and probably not clinically relevant. Grains of paradise raised energy use and slightly reduced belly (visceral) fat in a 4-week study of 19 young, non-obese women, but total body fat didn''t change. The probiotic B420, at the same 10 billion CFU dose used here, was tested for 6 months in 225 adults with overweight; in the main analysis no group differed from placebo in body fat, and benefits appeared only in a narrower analysis of people who followed the protocol. That trial was run by the company that makes B420.

Safety matters more than usual here. ODS reports at least 50 cases of liver damage linked to green tea extracts, with risk appearing higher on an empty stomach, and Arrae''s own label says not to take MB-1 on an empty stomach or with a history of liver problems. Chromium may cause low blood sugar with insulin or metformin and may reduce absorption of levothyroxine. One person with chronic kidney disease had kidney failure associated with African mango.', 'Arrae''s product page shows 4.68 out of 5 from 3,613 reviews. On Amazon it has 4.0 out of 5 stars from 274 ratings as of October 2026: 61% five stars, 12% four, 9% three, 5% two, and 13% one star; the Amazon reviews cover both the 40- and 60-capsule bottles. The first rating is from Arrae''s own site; the second is from Amazon''s product page.', 'No study of MB-1 was found. Its main ingredients have small, short trials with mixed quality; reviews call the African mango evidence limited, and chromium and green tea produce only about 1 kg more weight loss than placebo.', 'brand', 'Product claims are sourced from Arrae; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"arrae.com":"https://arrae.com/products/mb-1","Amazon":"https://www.amazon.com/dp/B0DCQC1DNS"},"ingredients":"Supplement Facts per the label shown on Amazon. Serving size 2 capsules; 30 servings per container (60 capsules). Vitamin B6 (as pyridoxal 5-phosphate 68%) 5 mg (294% DV). Chromium (as chromium picolinate) 500 mcg (1428% DV). Proprietary blend 895 mg: Cissus leaf extract (CQR-300), green tea extract, African mango seed extract (IGOB131), grains of paradise seed extract; amounts of each not disclosed. Probiotic 25 mg (10 billion CFU): Bifidobacterium lactis B420. Other ingredients: vegetable capsule (HPMC), rice hull (ground). Distributed by Arrae Inc, Dayton, NJ. Arrae''s own page lists the same formula in its Ingredients section, but its \"Full Ingredients List\" panel shows a different one (10 mg B6, a 1.35 g blend with African pepper, green tea, African mango and grains of paradise, and a 27 mg blend of three other probiotic strains), possibly for MB-1 Max or MB-1 45+.","doctorOpinionShort":"A metabolism blend whose \"up to 12%\" weight-loss claim comes from small ingredient studies, mainly one 10-week trial of 72 people, not from MB-1 itself. Reviews call the African mango evidence limited, and the blend''s doses aren''t disclosed. Contains green tea extract (rare liver injury) and chromium (can lower blood sugar with diabetes drugs). Not for pregnancy, nursing, under 18, or anyone on medication, per the label.","doctorOpinionCitations":[{"url":"https://arrae.com/products/mb-1","label":"arrae.com: MB-1, ingredients and claims"},{"url":"https://www.amazon.com/dp/B0DCQC1DNS","label":"Amazon: Arrae MB-1 listing, Supplement Facts and safety information"},{"url":"https://ods.od.nih.gov/factsheets/WeightLoss-HealthProfessional/","label":"NIH Office of Dietary Supplements: Dietary supplements for weight loss","chipLabel":"NIH ODS: weight-loss supplements"},{"url":"https://pubmed.ncbi.nlm.nih.gov/18377661/","label":"PubMed: Cissus quadrangularis/Irvingia gabonensis combination in weight loss, double-blind, placebo-controlled study (2008)","chipLabel":"Cissus + African mango trial, 72 people (2008)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/31855111/","label":"PubMed: Effects of Irvingia gabonensis seed extract supplementation, systematic review and meta-analysis (2020)","chipLabel":"African mango meta-analysis, 5 trials (2020)"}],"whoItsFor":["Healthy adults 18 and older, not pregnant or nursing, who want to try a supplement alongside diet and exercise and understand the evidence is limited","Not for anyone taking medications, with a medical condition, or with a history of liver problems (per the label)","Not a substitute for talking to a doctor about weight, blood sugar, or metabolism"],"howToUse":{"intro":"Per Arrae''s site and the Amazon listing: 2 capsules a day. Arrae recommends 3 months of daily use alongside a balanced diet and active lifestyle.","steps":["Take 2 capsules with your first meal of the day. The label says not to take it on an empty stomach.","If you are sensitive to caffeine, Arrae suggests taking one capsule at breakfast and one at lunch.","Take it earlier in the day, since it contains caffeine from green tea.","Don''t take more than 1 serving a day, and skip other green tea products that day (per the label)."],"sourceUrl":"https://arrae.com/products/mb-1","sourceLabel":"arrae.com: MB-1"},"warnings":["Pregnant, nursing, or under 18: don''t use (per the label).","Taking any medication or have a medical condition: don''t use unless your doctor approves (per the label). Chromium may cause low blood sugar with insulin or metformin and may reduce levothyroxine absorption (NIH ODS).","History of liver problems: don''t use (per the label). Green tea extract has been linked to rare liver injury (NIH ODS).","Don''t take it on an empty stomach or with other green tea products the same day (per the label).","Kidney disease: one case of kidney failure has been associated with African mango (NIH ODS); check with your doctor first.","Contains caffeine."],"ingredientScience":[{"name":"African mango (IGOB131) with Cissus (CQR-300)","text":"Arrae''s \"up to 12%\" body weight, blood sugar, and waist figures cite these two together. In a 10-week, randomized, double-blind, placebo-controlled trial by a research group in Cameroon, 72 adults with overweight or obesity took Cissus alone, Cissus with African mango, or a placebo. Both active groups had significantly lower body weight, body fat, waist size, cholesterol, and blood sugar than placebo, with larger changes for the combination. MB-1 doesn''t disclose how much of either extract it contains.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18377661/","label":"PubMed: The use of a Cissus quadrangularis/Irvingia gabonensis combination in the management of weight loss, double-blind, placebo-controlled study (2008)"}]},{"name":"African mango (Irvingia gabonensis)","text":"A 2013 systematic review found three trials, all by the same authors and all with reporting flaws; each reported weight loss, but the reviewers concluded the effect was unproven and that it can''t be recommended as a weight-loss aid. A 2020 meta-analysis of five trials rated four as having a high risk of bias, and the only low-risk trial found no significant difference in weight. NIH ODS says it appears well tolerated (headache, sleep trouble, and gas were reported) but human safety hasn''t been rigorously studied, and one person with chronic kidney disease had kidney failure associated with it.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23419021/","label":"PubMed: The efficacy of Irvingia gabonensis supplementation in the management of overweight and obesity, systematic review (2013)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/31855111/","label":"PubMed: Effects of Irvingia gabonensis seed extract supplementation on anthropometric and cardiovascular outcomes, systematic review and meta-analysis (2020)"},{"url":"https://ods.od.nih.gov/factsheets/WeightLoss-HealthProfessional/","label":"NIH Office of Dietary Supplements: Dietary supplements for weight loss"}]},{"name":"Green tea extract","text":"Arrae states it supports metabolism. NIH ODS concludes any weight effect of green tea is small and probably not clinically relevant (about 1 kg more than placebo in a review of 14 trials, with no difference in the studies done outside Japan). ODS also reports at least 50 cases of liver damage linked to green tea extracts since 2006, with risk appearing higher when taken on an empty stomach.","citations":[{"url":"https://ods.od.nih.gov/factsheets/WeightLoss-HealthProfessional/","label":"NIH Office of Dietary Supplements: Dietary supplements for weight loss"}]},{"name":"Chromium (500 mcg as chromium picolinate)","text":"Arrae states it supports metabolic function and blood sugar. NIH ODS says a review of 9 trials found about 1.1 kg more weight loss than placebo, of debatable clinical relevance, and that clinical trials found only a very small benefit. Chromium may cause low blood sugar when taken with insulin or metformin and may reduce absorption of levothyroxine. People with kidney or liver disease should be cautious with high amounts.","citations":[{"url":"https://ods.od.nih.gov/factsheets/Chromium-Consumer/","label":"NIH Office of Dietary Supplements: Chromium fact sheet for consumers"},{"url":"https://ods.od.nih.gov/factsheets/WeightLoss-HealthProfessional/","label":"NIH Office of Dietary Supplements: Dietary supplements for weight loss"}]},{"name":"Grains of paradise (Aframomum melegueta)","text":"Arrae states it boosts daily calorie burn. In a 4-week, single-blind, placebo-controlled crossover study of 19 non-obese women aged 20 to 22, a daily 30 mg extract increased whole-body energy use and slightly reduced belly (visceral) fat, but total and under-the-skin fat didn''t change. MB-1 doesn''t disclose how much it contains.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24759256/","label":"PubMed: Daily ingestion of grains of paradise (Aframomum melegueta) extract increases whole-body energy expenditure and decreases visceral fat in humans (2014)"}]},{"name":"Bifidobacterium lactis B420 (10 billion CFU)","text":"Arrae calls it a clinically studied strain for bloating and gut balance. In a 6-month, double-blind trial of 225 adults with overweight, B420 at the same 10 billion CFU daily dose did not change body fat compared with placebo in the main analysis. Among the people who followed the protocol, B420 with fiber reduced body fat by 4.5% relative to placebo, while B420 alone did not differ significantly. The study was run by DuPont, which makes B420.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/27810310/","label":"PubMed: Probiotic with or without fiber controls body fat mass, associated with serum zonulin, in overweight and obese adults, randomized controlled trial (2016)"}]},{"name":"Vitamin B6 (5 mg as P5P)","text":"This is 294% of the daily value. NIH ODS sets the adult upper limit at 100 mg a day (Europe''s food safety agency set a lower limit of 12 mg in 2023), so 5 mg is well below both.","citations":[{"url":"https://ods.od.nih.gov/factsheets/VitaminB6-Consumer/","label":"NIH Office of Dietary Supplements: Vitamin B6 fact sheet for consumers"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0DCQC1DNS","text":"Amazon: Arrae MB-1 reviews","summary":"4.0 out of 5 stars from 274 ratings on Amazon as of October 2026; 13% of ratings are one star."},{"platform":"website","url":"https://arrae.com/products/mb-1","text":"arrae.com: MB-1 customer reviews","summary":"Arrae''s own product page shows 4.68 out of 5 from 3,613 reviews."}]}},"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb)
